{"command":"python3 << 'PY'
import json, subprocess, sys

def gql(query, variables=None):
    cmd = ["gh", "api", "graphql", "-f", f"query={query}"]
    if variables:
        for k, v in variables.items():
            cmd.extend(["-f", f"{k}={v}"])
    out = subprocess.check_output(cmd, text=True)
    data = json.loads(out)
    if "errors" in data:
        print(json.dumps(data["errors"], indent=2), file=sys.stderr)
        sys.exit(1)
    return data["data"]

q_user = '''
query($cursor: String) {
  user(login: "repr0bated") {
    repositories(first: 100, isFork: true, ownerAffiliations: OWNER, after: $cursor, orderBy: {field: NAME, direction: ASC}) {
      pageInfo { hasNextPage endCursor }
      nodes {
        nameWithOwner
        url
        isPrivate
        isArchived
        pushedAt
        description
        parent { nameWithOwner url isPrivate owner { login } }
      }
    }
  }
}
'''
q_org = '''
query($cursor: String) {
  organization(login: "3tched-com") {
    repositories(first: 100, isFork: true, after: $cursor, orderBy: {field: NAME, direction: ASC}) {
      pageInfo { hasNextPage endCursor }
      nodes {
        nameWithOwner
        url
        isPrivate
        isArchived
        pushedAt
        description
        parent { nameWithOwner url isPrivate owner { login } }
      }
    }
  }
}
'''

def pages(query, root):
    cursor = None
    rows = []
    while True:
        variables = {}
        # gh api graphql needs variables as -F for null? Use separate queries
        if cursor is None:
            q = query.replace("$cursor: String", "").replace("after: $cursor,", "")
            data = gql(q)
        else:
            data = gql(query, {"cursor": cursor})
        block = data[root]["repositories"]
        rows.extend(block["nodes"])
        if not block["pageInfo"]["hasNextPage"]:
            break
        cursor = block["pageInfo"]["endCursor"]
    return rows

user_rows = pages(q_user, "user")
org_rows = pages(q_org, "organization")
all_rows = user_rows + org_rows
print(f"COUNT {len(all_rows)} personal={len(user_rows)} org={len(org_rows)}", file=sys.stderr)

# group by parent owner
from collections import Counter
owners = Counter((r["parent"] or {}).get("owner", {}).get("login") or "?" for r in all_rows)
print("PARENT_OWNERS", file=sys.stderr)
for o, n in owners.most_common():
    print(f"  {n:3} {o}", file=sys.stderr)

# write json for later
with open("/tmp/forks.json", "w") as f:
    json.dump(all_rows, f, indent=2)

for r in all_rows:
    p = r.get("parent") or {}
    flags = []
    if r["isPrivate"]: flags.append("private")
    if r["isArchived"]: flags.append("archived")
    flag = ",".join(flags) if flags else "public"
    print(f"{r['nameWithOwner']}\t{p.get('nameWithOwner','?')}\t{flag}\t{(r.get('pushedAt') or '')[:10]}\t{r['url']}")
PY","description":"List all GitHub forks with parent repos"}

